raw:
{
  "conflicts": [
    {
      "drug": "metformin 1 MG Oral Tablet",
      "condition": "End-stage renal disease (disorder)",
      "reason": "患者同时诊断CKD 4期及终末期肾病，入院eGFR仅5.5 mL/min；严重肾功能不全（eGFR<30）禁用二甲双胍，以免药物蓄积引发乳酸性酸中毒。"
    },
    {
      "drug": "ibuprofen 1 MG Oral Tablet",
      "condition": "End-stage renal disease (disorder)",
      "reason": "终末期肾病/晚期CKD应避免使用布洛芬等NSAID，可进一步损害残余肾功能，并引起高钾血症、水钠潴留及心血管风险。"
    },
    {
      "drug": "ketorolac 1 MG Oral Tablet",
      "condition": "End-stage renal disease (disorder)",
      "reason": "酮咯酸禁用于晚期肾功能不全；患者为终末期肾病，使用可导致急性肾损伤、肾功能进一步恶化及出血风险增加。"
    },
    {
      "drug": "naproxen 1 MG Oral Tablet",
      "condition": "End-stage renal disease (disorder)",
      "reason": "终末期肾病/晚期CKD应避免使用萘普生等NSAID，以免加重肾损伤，并导致高钾血症、水钠潴留和血压恶化。"
    }
  ],
  "data_issues": [
    {
      "type": "诊断分期矛盾",
      "detail": "同一次住院诊断同时列出CKD 1、2、3、4期及终末期肾病，未注明各条目的历史或当前状态，需核实当前肾功能分期。"
    },
    {
      "type": "医嘱剂量及字段异常",
      "detail": "二甲双胍、布洛芬、酮咯酸和萘普生均记录为“1 MG Oral Tablet”，剂量明显不符合常规制剂规格，且dose_val_rx、dose_unit_rx和route等字段缺失，无法完成剂量审核。"
    },
    {
      "type": "肾功能检验记录不一致",
      "detail": "入院血肌酐2.7 mg/dL、eGFR 5.5 mL/min，次日血肌酐突然降至0.9 mg/dL并在此后多次完全重复，与终末期肾病诊断缺乏相应治疗或检验说明，需核实结果及是否存在透析、移植等未记录事件。"
    }
  ]
}

