raw:
{
  "discharge_meds": [
    "metformin",
    "ibuprofen",
    "ketorolac",
    "naproxen",
    "tacrolimus"
  ],
  "recheck_labs": [
    "Glomerular filtration rate",
    "Erythrocytes",
    "Chloride"
  ],
  "warnings": [
    "终末期肾病及肾移植病史患者同时使用布洛芬、酮咯酸、萘普生三种NSAIDs，可能导致急性肾损伤、移植肾功能恶化、消化道出血及心血管事件，出院前必须由医师复核，避免自行合用。",
